"""Layer in GW (notes 21.17): the candidate's layer learns the supply shift implied by known prices as a function of demand and hour; the market is then
cleared with the predicted shift. usage: mm_gw_score.py RUN MOD   (after: MOD=<MOD> mm_layer.py RUN gw)"""
import sys, os, importlib, subprocess, numpy as np, warnings; warnings.filterwarnings("ignore")
RUN, MOD = sys.argv[1], sys.argv[2]; M = importlib.import_module(MOD); SP = M.SP; th = {k: float(np.median(v)) for k, v in np.load(f"{SP}/out/{MOD}_post.npz").items() if np.ndim(v) == 1}; CR = {"winter": "hw2", "summer": "hs2", "autumn": "ha"}; TS = {"winter": ("win_ts", "median"), "summer": ("ssn_ts", "median"), "autumn": ("tsl_123_8k", "vint")}; hr = np.arange(56) // 4
for per in ("winter", "summer", "autumn"):
    subprocess.run([sys.executable, "dyn2.py", per, RUN, "known,ts", "x+xh"], capture_output=True); I = np.load(f"{SP}/out/inputs_{per}.npz"); a = I["actual"].astype(float); rl = I["rl_true"].astype(float)[:, :56]; U = np.load(f"{SP}/out/structfc_{RUN}_known_dyn2xxh.npz")["vint"].astype(float); P = np.zeros_like(a); P0 = np.zeros_like(a)
    for j, c in enumerate(I["cutoffs"]):
        z = np.load(f"{SP}/out/struct_{RUN}/{str(c)[:10]}.npz"); x = z["x_known"].astype(float); Lj = float(z["Lj"]); tj = dict(zip([str(k) for k in z["thk"]], z["thv"].astype(float))) if "thv" in z.files else th; es = z["eu_shift"].astype(float) if "eu_shift" in z.files else 0.0; P[j] = M.clear(tj, x, np.full(153, Lj), eps=U[j] + es)[0] / 10; P0[j] = M.clear(tj, x, np.full(153, Lj))[0] / 10
    Ut = np.load(f"{SP}/out/structfc_{RUN}_ts_dyn2xxh.npz")["vint"].astype(float); Pt = np.zeros_like(a)
    for j, c in enumerate(I["cutoffs"]): z = np.load(f"{SP}/out/struct_{RUN}/{str(c)[:10]}.npz"); tj = dict(zip([str(k) for k in z["thk"]], z["thv"].astype(float))) if "thv" in z.files else th; es = z["eu_shift"].astype(float) if "eu_shift" in z.files else 0.0; Pt[j] = M.clear(tj, z["x_ts"].astype(float), np.full(153, float(z["Lj"])), eps=Ut[j] + es)[0] / 10
    tsf, tsk = TS[per]; tp = np.load(f"{SP}/out/{tsf}.npz")[tsk].astype(float); ct = np.load(f"{SP}/out/structfc_{CR[per]}_ts_dyn2xxh.npz")["vint"].astype(float); s2 = lambda v: f"{np.abs(v - a)[:, :32].mean():.2f} / {np.abs(v - a)[:, :56].mean():.2f}"
    print(f"{per} FORECAST LOAD (Timestral): {MOD} + layer in GW {s2(Pt)} | candidate's curve + layer {s2(ct)} | Timestral price alone {s2(tp)} | 50/50 market model + Timestral {s2(0.5 * (Pt + tp))} | candidate (curve + layer, 50/50 Timestral) {s2(0.5 * (ct + tp))} | all three equally {s2((Pt + ct + tp) / 3)}")
    np.savez_compressed(f"{SP}/out/structfc_{RUN}_{per}_price.npz", vint=P.astype(np.float32), bare=P0.astype(np.float32), u=U.astype(np.float32), vint_ts=Pt.astype(np.float32)); cv = np.load(f"{SP}/out/structfc_{CR[per]}_known_dyn2xxh.npz")["vint"].astype(float); sc = lambda v: f"{np.abs(v - a)[:, :32].mean():.2f} / {np.abs(v - a)[:, :56].mean():.2f}"
    ec = np.abs(cv - a)[:, :56]; em = np.abs(P - a)[:, :56]; A = a[:, :56]
    print(f"{per}: {MOD} bare {sc(P0)} | with the layer in GW {sc(P)} | candidate's curve + layer (true load) {sc(cv)} | bias {np.mean((P - a)[:, :56]):+.2f}")
    print("   by residual load (candidate vs this):  " + "  ".join(f"{lo}..{hi}: {ec[(rl >= lo) & (rl < hi)].mean():.2f} vs {em[(rl >= lo) & (rl < hi)].mean():.2f}" for lo, hi in ((-40, 5), (5, 15), (15, 25), (25, 35), (35, 45), (45, 80)) if ((rl >= lo) & (rl < hi)).sum() > 40))
    print("   by price level ct:  " + "  ".join(f"{lo}..{hi}: {ec[(A >= lo) & (A < hi)].mean():.2f} vs {em[(A >= lo) & (A < hi)].mean():.2f}" for lo, hi in ((-50, 0.05), (0.05, 5), (5, 10), (10, 15), (15, 25), (25, 200)) if ((A >= lo) & (A < hi)).sum() > 40))
